//! Bit-exact check of `actor::point_inside_quad_planes` against
//! `tests/fixtures/point_inside_quad.txt`, generated by
//! `Build/actor_fixture_harness/pq_bits.cpp` built with `-O3 -ffp-contract=on`.
//! The fixture differs from a `-ffp-contract=off` build on every case, so this
//! test fails if any `mul_add` site in `actor.rs` is unfused or fused wrongly.

use hp2_abi::FVector;
use hp2_engine::actor::point_inside_quad_planes;

fn f(hex: &str) -> f32 {
    f32::from_bits(u32::from_str_radix(hex, 16).expect("hex f32 bits"))
}

fn vec3(it: &mut std::str::SplitWhitespace<'_>) -> FVector {
    FVector {
        x: f(it.next().unwrap()),
        y: f(it.next().unwrap()),
        z: f(it.next().unwrap()),
    }
}

#[test]
fn point_inside_quad_matches_contracted_cpp_bits() {
    let text = include_str!("fixtures/point_inside_quad.txt");
    let mut cases = 0usize;
    for line in text.lines() {
        let mut it = line.split_whitespace();
        assert_eq!(it.next(), Some("case"));
        let idx: usize = it.next().unwrap().parse().unwrap();
        assert_eq!(it.next(), Some("in"));
        let mut verts = [FVector {
            x: 0.0,
            y: 0.0,
            z: 0.0,
        }; 4];
        for v in &mut verts {
            *v = vec3(&mut it);
        }
        let normal = vec3(&mut it);
        let point = vec3(&mut it);
        assert_eq!(it.next(), Some("out"));
        let planes_n: usize = it.next().unwrap().parse().unwrap();
        let mut want = Vec::with_capacity(planes_n);
        for _ in 0..planes_n {
            let n = vec3(&mut it);
            let w = f(it.next().unwrap());
            let d = f(it.next().unwrap());
            want.push((n, w, d));
        }
        let want_result: u32 = it.next().unwrap().parse().unwrap();

        let (got_result, got) = point_inside_quad_planes(point, &verts, normal);
        assert_eq!(got.len(), want.len(), "case {idx}: plane count");
        for (p, (g, w)) in got.iter().zip(&want).enumerate() {
            let (gn, gw, gd) = *g;
            let (wn, ww, wd) = *w;
            for (name, a, b) in [
                ("cn.x", gn.x, wn.x),
                ("cn.y", gn.y, wn.y),
                ("cn.z", gn.z, wn.z),
                ("w", gw, ww),
                ("dot", gd, wd),
            ] {
                assert_eq!(
                    a.to_bits(),
                    b.to_bits(),
                    "case {idx} plane {p} {name}: got {a:e} want {b:e}"
                );
            }
        }
        assert_eq!(got_result as u32, want_result, "case {idx}: result");
        cases += 1;
    }
    assert_eq!(cases, 200);
}
